const modulesNames = {
    'calcAge' : 'Calc Age',
    'mapString': 'Map String'
}

const getModuleName = (module = '') => {
    return !!modulesNames[module] ? `${modulesNames[module]} Module` : '';
}

export const logError = (message, module = '') => {
    console.log(module)
    console.error(`Error ${getModuleName(module)}: `, message);
}